import path from 'node:path';import readline from 'node:readline';import {pathToFileURL} from 'node:url';import {Worker} from 'node:worker_threads';
const root=process.env.CAD_BACKEND_RELEASE_DIR,code=path.join(root,'runtime');
const {backendRuntimeInfo}=await import(pathToFileURL(path.join(code,'gateway/backend-runtime.mjs')));backendRuntimeInfo(code);
const {MeshArtifactPool}=await import(pathToFileURL(path.join(code,'gateway/mesh-artifact-pool.mjs'))),{MeshJobStore}=await import(pathToFileURL(path.join(code,'gateway/mesh-job-store.mjs')));
const store=new MeshJobStore(process.env.TEST_DATA_ROOT),pool=new MeshArtifactPool({dataDir:process.env.TEST_DATA_ROOT,workerFactory:(url,options)=>{if(process.env.TEST_TAMPER_ADMISSION_RECEIPT==='1'&&options.workerData.admissionMemo)options.workerData.admissionMemo.receipt.admission.usable=!options.workerData.admissionMemo.receipt.admission.usable;return new Worker(url,options);}});
try{for await(const line of readline.createInterface({input:process.stdin})){const input=JSON.parse(line);if(input.close)break;try{const base=store.load().find(job=>job.jobId===input.jobId),job={...base,...input.overrides},result=await pool.execute({operation:'read',job});process.stdout.write(JSON.stringify({ok:true,admission:result.mesh.admission,status:pool.status()})+'\n');}catch(error){process.stdout.write(JSON.stringify({ok:false,code:error.code,error:error.message,status:pool.status()})+'\n');}}}finally{await pool.close();}
